// SEMT0043 - M5StampC3 starter
// Reads the Pololu 3Pi+ IMU (LSM6 + LIS3MDL) over I2C.

#include <Arduino.h>
#include <Wire.h>
#include <LIS3MDL.h>
#include <LSM6.h>

// I2C pins - change these to match your wiring on the StampC3.
#ifndef I2C_SDA_PIN
#define I2C_SDA_PIN 0
#endif
#ifndef I2C_SCL_PIN
#define I2C_SCL_PIN 1
#endif

LSM6 imu;
LIS3MDL mag;
bool imuReady = false;
bool magReady = false;

void scanI2C() {
  Serial.println("Scanning I2C bus...");
  for (uint8_t addr = 1; addr < 127; addr++) {
    Wire.beginTransmission(addr);
    if (Wire.endTransmission() == 0) {
      Serial.printf("  found device at 0x%02X\n", addr);
    }
  }
}

void setup() {
  Serial.begin(115200);
  delay(250);
  Serial.println();
  Serial.println("M5StampC3 / Pololu 3Pi+ IMU starter");
  Wire.begin(I2C_SDA_PIN, I2C_SCL_PIN);
  Wire.setClock(400000);
  scanI2C();

  imuReady = imu.init();
  if (imuReady) { imu.enableDefault(); Serial.println("LSM6 OK"); }
  else Serial.println("LSM6 not found (check wiring/address)");

  magReady = mag.init();
  if (magReady) { mag.enableDefault(); Serial.println("LIS3MDL OK"); }
  else Serial.println("LIS3MDL not found (check wiring/address)");
}

void loop() {
  if (imuReady) {
    imu.read();
    Serial.printf("accel: %6d %6d %6d   gyro: %6d %6d %6d\n", imu.a.x, imu.a.y, imu.a.z, imu.g.x, imu.g.y, imu.g.z);
  }
  if (magReady) {
    mag.read();
    Serial.printf("mag:   %6d %6d %6d\n", mag.m.x, mag.m.y, mag.m.z);
  }
  delay(100);
}
```

